ValidationRule.errorConditionFormula:
AND(
    OR(
        NOT(ISBLANK(Consignor_Pincode__c)),
        NOT(ISBLANK(Consignee_Pincode__c))
    ),
    OR(
        AND(
            NOT(ISBLANK(Consignor_Pincode__c)),
            NOT(
                REGEX(
                    Consignor_Pincode__c,
                    "^[1-9][0-9]{5}$"
                )
            )
        ),
        AND(
            NOT(ISBLANK(Consignee_Pincode__c)),
            NOT(
                REGEX(
                    Consignee_Pincode__c,
                    "^[1-9][0-9]{5}$"
                )
            )
        )
    )
)
